var builder = WebApplication.CreateBuilder(args);

// Native AOT compatible DI registrations
// Use the AOT analyzer to find issues

builder.Services.AddHttpClient<IChatClient, OpenAIChatClient>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    return new OpenAIChatClient(
        config["OpenAI:ApiKey"],
        new OpenAIClientSettings
        {
            Endpoint = new Uri(config["OpenAI:BaseUrl"]),
            Organization = config["OpenAI:OrgId"]
        });
});

// For Microsoft.Extensions.AI, use the concrete types directly
// Avoid generic constraints that require reflection

builder.Services.AddSingleton<AIAgentService>();

builder.Services.Configure<AIServiceOptions>(builder.Configuration.GetSection("AI"));

// Use AOT-compatible JSON options
builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.TypeInfoResolverChain = [AppJsonSerializerContext.Default];
});

var app = builder.Build();
app.MapPost("/api/chat", async (
    ChatRequest request, IChatClient client) =>
    await StreamResponse(client, request));
app.Run();
